export function clamp(t,o,r){return Math.min(Math.max(t,o),r)}export function squaredSegmentDistance(t,o,r,n,u,c){const i=u-r,e=c-n;if(i!==0||e!==0){const f=((t-r)*i+(o-n)*e)/(i*i+e*e);f>1?(r=u,n=c):f>0&&(r+=i*f,n+=e*f)}return squaredDistance(t,o,r,n)}export function squaredDistance(t,o,r,n){const u=r-t,c=n-o;return u*u+c*c}export function solveLinearSystem(t){const o=t.length;for(let n=0;n<o;n++){let u=n,c=Math.abs(t[n][n]);for(let e=n+1;e<o;e++){const f=Math.abs(t[e][n]);f>c&&(c=f,u=e)}if(c===0)return null;const i=t[u];t[u]=t[n],t[n]=i;for(let e=n+1;e<o;e++){const f=-t[e][n]/t[n][n];for(let s=n;s<o+1;s++)n==s?t[e][s]=0:t[e][s]+=f*t[n][s]}}const r=new Array(o);for(let n=o-1;n>=0;n--){r[n]=t[n][o]/t[n][n];for(let u=n-1;u>=0;u--)t[u][o]-=t[u][n]*r[n]}return r}export function toDegrees(t){return t*180/Math.PI}export function toRadians(t){return t*Math.PI/180}export function modulo(t,o){const r=t%o;return r*o<0?r+o:r}export function lerp(t,o,r){return t+r*(o-t)}export function toFixed(t,o){const r=Math.pow(10,o);return Math.round(t*r)/r}export function round(t,o){return Math.round(toFixed(t,o))}export function floor(t,o){return Math.floor(toFixed(t,o))}export function ceil(t,o){return Math.ceil(toFixed(t,o))}
